      {
        "id": "ex-murphy-cellular-basis-for-h3",
        "kind": "example",
        "title": "The Murphy cellular basis of H(S_3)",
        "deps": [
          "def-hecke-jucys-murphy-elements-and-q-contents",
          "def-cellular-algebra-basis-and-cell-module",
          "def-murphy-elements-and-murphy-tableau-elements",
